#!/usr/bin/env python3
"""Generate the complete Markdown documentation catalog, without network access."""
from __future__ import annotations
import argparse
import difflib
from itertools import islice
from pathlib import Path
from urllib.parse import quote

SKIP_DIRS = {".git", ".venv", "venv", "node_modules", "__pycache__"}
OUTPUT = "DOCUMENTATION_INDEX.md"


def slug(name: str) -> str:
    # Matches the simple ASCII section headings generated by this script.
    return "".join(c.lower() if c.isalnum() or c in " -" else "" for c in name).replace(" ", "-")


def paths(root: Path) -> list[str]:
    return sorted(
        p.relative_to(root).as_posix()
        for p in root.rglob("*.md")
        if not SKIP_DIRS.intersection(p.relative_to(root).parts)
        and p.relative_to(root).as_posix() != OUTPUT
    )


def render(all_paths: list[str]) -> str:
    groups: dict[str, list[str]] = {}
    for path in all_paths:
        name = path.split("/")[0] if "/" in path else "Root Guides & Repository Documents"
        groups.setdefault(name, []).append(path)
    names = sorted(groups, key=lambda s: (s != "Root Guides & Repository Documents", s))
    lines = [
        "# Complete Documentation Index", "",
        f"**{len(all_paths)} Markdown documents indexed.** Generated from the tracked repository tree as of this revision. This index links all documentation pages, including nested guides that may not appear in a section README.",
        "",
        "Prefer [Start Here](START_HERE.md) for a curated learning route, [Main README](README.md) for topic navigation, or the [PNWC Cyberdeck Public Reference](Cyberdeck/README.md) for the portable assessment project.",
        "", "## Browse By Section", "",
        "| Section | Documents | Open |", "| --- | ---: | --- |",
    ]
    for name in names:
        lines.append(f"| {name} | {len(groups[name])} | [Open section](#{slug(name)}) |")
    for name in names:
        lines.extend(("", "## " + name, "", "| Document | Repository Path |", "| --- | --- |"))
        for path in groups[name]:
            segments = path.split("/")
            if len(segments) == 1:
                title = path
            elif segments[-1] == "README.md":
                title = "README — " + "/".join(segments[:-1])
            else:
                title = "/".join(segments[1:])
            title = title.replace("|", " / ")
            lines.append(f"| [{title}](./{quote(path, safe='/')}) | `{path.replace(chr(96), chr(39))}` |")
    lines.extend(("", "---", "", "**Maintaining this index:** add/remove a Markdown page, then regenerate and review the index. File existence and repository links are checked in CI; a listing here does not certify technical accuracy or the safety of sample commands.", ""))
    return "\n".join(lines)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Fail if the committed index is stale")
    args = parser.parse_args()
    root = Path(__file__).resolve().parents[1]
    result = render(paths(root))
    target = root / OUTPUT
    if args.check:
        if not target.is_file() or target.read_text(encoding="utf-8") != result:
            print("DOCUMENTATION_INDEX.md is stale; run python tools/generate_documentation_index.py")
            previous = target.read_text(encoding="utf-8") if target.is_file() else ""
            for line in islice(difflib.unified_diff(previous.splitlines(), result.splitlines(), fromfile="committed", tofile="generated", lineterm=""), 60):
                print(line)
            return 1
        print(f"Documentation catalog current: {len(paths(root))} Markdown files.")
        return 0
    target.write_text(result, encoding="utf-8")
    print(f"Updated {target} with {len(paths(root))} documents.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
